insert into public.tasks (owner_id,id,room,name,frequency,interval_days,interval_months,last_done,planned_date,stagger_date,due_weekday,season,priority,effort_min,notes,active,sort_key,plan_text,plan_date,source,history,supplies) select id,'11b6335f-23ac-50b4-85bf-567526444180','Kitchen','Clean behind/around washing machine & dishwasher (where accessible)','Yearly',365,12,'2025-11-07',null,'2026-10-31',null,null,'Nice-to-have',30,'Built-in machines usually don''t pull out: pop off the kickboard, vacuum/wipe underneath and the side gaps, check hoses for leaks. Only pull out a freestanding machine (unplug, water off).',true,18,'Staggered (was 07 Nov)','2026-10-31','New','New task. Integrated/built-in appliances usually can''t be pulled out - in that case pop off the kickboard/plinth and vacuum/wipe underneath and the gaps at the sides, check for leaks under the hoses. Only pull a freestanding machine out if it moves easily (unplug, turn off the water, mind the hoses). Behind-fridge not included (integrated fridge). Last done back-calculated so the first due date lands on a quiet weekend.; Staggered: the next due moves from Sat 07 Nov 2026 to Sat 31 Oct 2026 (one-off Stagger date, column U) so weekends spread out; once done it recurs yearly from then',null from _me;
insert into public.tasks (owner_id,id,room,name,frequency,interval_days,interval_months,last_done,planned_date,stagger_date,due_weekday,season,priority,effort_min,notes,active,sort_key,plan_text,plan_date,source,history,supplies) select id,'26049db0-0398-5d72-ab21-15e00167750a','Kitchen','Clean kitchen cabinet fronts','Quarterly',91,3,'2026-09-12',null,'2026-10-31',null,null,'Nice-to-have',20,'Doors, drawer fronts & handles (outside only - insides are ''Organise & wipe cupboards''). Warm water + a little washing-up liquid, dry after.',true,19,'Staggered (was 12 Dec)','2026-10-31','New','New task. Doors, drawer fronts and handles (outside only - insides are ''Organise & wipe cupboards''). Warm water + a little washing-up liquid, dry after. Last done back-calculated so the first due date lands on a quiet weekend.; Staggered: the next due moves from Sat 12 Dec 2026 to Sat 31 Oct 2026 (one-off Stagger date, column U) so weekends spread out; once done it recurs quarterly from then',null from _me;
insert into public.tasks (owner_id,id,room,name,frequency,interval_days,interval_months,last_done,planned_date,stagger_date,due_weekday,season,priority,effort_min,notes,active,sort_key,plan_text,plan_date,source,history,supplies) select id,'56b45daa-8e52-59bb-b9ea-70b71bb5fd6a','Kitchen','Replace Scrub Daddy sponge','Every 2 months',60,2,'2026-09-07',null,null,null,null,'Hygiene',2,'Replace sooner if torn, crumbly or smelly. Sanitise weekly: dishwasher top rack, or damp in the microwave max 60 s. No bleach. Sources: https://support.scrubdaddy.com ; https://www.scrubdaddy.ph/pages/faq',true,20,null,null,'New','New task. Scrub Daddy gives no fixed lifespan (depends on use; rough surfaces/harsh chemicals wear it faster) - replace sooner if torn, crumbly or smelly. Every 2 months matches their claim that FlexTexture foam is lab-tested not to hold odours for up to 8 weeks. Between replacements: rinse under warm water after use and let it dry; sanitise in the dishwasher TOP rack, or dampen and microwave for no more than 60 s. No bleach. Old one can be retired to bathroom/outdoor jobs. Sources: https://support.scrubdaddy.com/support/solutions/articles/156000293551-how-long-do-your-scrubbers-last- ; https://support.scrubdaddy.com/support/solutions/articles/156000293558-is-scrub-daddy-top-rack-dishwasher-safe- ; https://www.scrubdaddy.ph/pages/faq (8-week odour claim, microwave 60 s, no bleach) ; https://scrubdaddy.net.au/faqs/ Last done back-calculated so the first due date lands on a quiet weekend.','Scrub Daddy sponge' from _me;
