insert into public.tasks (owner_id,id,room,name,frequency,interval_days,interval_months,last_done,planned_date,stagger_date,due_weekday,season,priority,effort_min,notes,active,sort_key,plan_text,plan_date,source,history,supplies) select id,'1752ea44-a0ae-5e42-af30-49b959644b2b','General','Check fire extinguisher (gauge in green, pin & seal intact, accessible)','Monthly',30,1,null,'2026-10-23',null,null,null,'Safety',2,'In place & unobstructed, pin + seal intact, no damage/rust, gauge in green; replace if used or >10 yrs. Fire blanket: accessible, replace if used or >7 yrs. Source: https://www.fireproductsdirect.ie/our-guide-to-maintaining-fire-safety-equipment-in-your-home/',true,83,'Catch-up Fri 23 Oct','2026-10-23','New','New task. Monthly user check: in its place and unobstructed; pin and tamper seal intact; no damage, rust or leaks; gauge needle in the green (if not, get it serviced/replaced); replace after any use or if >10 years old. No legal requirement for a professional service at home. Fire blanket (if you have one, ideally in the kitchen): at the same time glance that it is accessible and the case/tapes are intact; inspect properly yearly and replace if used, damaged or >7 years old. Sources: Fire Products Direct (IE) home guide https://www.fireproductsdirect.ie/our-guide-to-maintaining-fire-safety-equipment-in-your-home/ ; IS 291 monthly user checks https://www.fireproductsdirect.ie/resources/how-to-use-a-fire-extinguisher/ ; HSA extinguisher checks https://www.hsa.ie/media/riop52fh/103525-hsa-2-fire-extinguisher-data-sheet.pdf ; Longford Co. Co. fire service (blankets) https://www.longfordcoco.ie/services/emergency-services/fire-service/fire-safety-and-prevention/fire-extinguishers-and-fire-blankets/ Planned date override (Last done blank until done).',null from _me;
