insert into public.tasks (owner_id,id,room,name,frequency,interval_days,interval_months,last_done,planned_date,stagger_date,due_weekday,season,priority,effort_min,notes,active,sort_key,plan_text,plan_date,source,history,supplies) select id,'6694921c-6f60-536e-b8a4-af256f4dd7c8','General','Test smoke/gas detectors & purifier CO alarms (x2)','Monthly',30,1,null,'2026-10-23',null,null,null,'Safety',8,'Press test on each alarm. Purifiers: hold [CO Alert] 3 s on each (sounds 5 s); also after holidays. CO sensor lasts 5 yrs. Not a substitute for a certified CO alarm near the boiler. Source: Hoover manual https://d15v10x8t3bz3x.cloudfront.net/Libretti/2020/10/16033331/48032691_H-Purifier%20300%20UM%20UK',true,86,'Catch-up Fri 23 Oct','2026-10-23','Both','Re-dated for catch-up Fri 23/10/2026 (was 269 days overdue); Planned date override (Last done blank until done); Frequency changed from Half-yearly; Renamed from ''Test smoke/gas detectors'' (CO alarm test folded in); Purifier CO alarms: touch [CO Alert] for 3 s on each Hoover H-Purifier 300 - alarm rings loudly for 5 s; test monthly AND after a prolonged absence (e.g. holidays). If it doesn''t ring, or the display shows CO sensor faulty/end of life, contact Hoover customer care. CO sensor expected lifetime is 5 years and must then be replaced (check the CO Sensor Condition lamp shows green). The manual says the purifier CO monitor is supplemental only and NOT a substitute for a certified EN 50291 CO alarm - keep a proper CO alarm near the boiler. Source: Hoover H-Purifier 300 user manual https://d15v10x8t3bz3x.cloudfront.net/Libretti/2020/10/16033331/48032691_H-Purifier%20300%20UM%20UK',null from _me;
