insert into public.tasks (owner_id,id,room,name,frequency,interval_days,interval_months,last_done,planned_date,stagger_date,due_weekday,season,priority,effort_min,notes,active,sort_key,plan_text,plan_date,source,history,supplies) select id,'d63f74ff-6613-58f3-bf8e-c9ccc0755cf8','General','Air purifiers (x2): vacuum filter outer mesh / pre-filter','Monthly',30,1,null,'2026-10-25',null,null,null,'Hygiene',15,'Both units: unplug, remove inlet cover, vacuum the filter''s outer mesh, refit, hold FILTER CLEANING 3 s. Also whenever that button turns yellow. Never wash. Source: https://d15v10x8t3bz3x.cloudfront.net/Libretti/2020/10/16033331/48032691_H-Purifier%20300%20UM%20UK',true,91,'Catch-up Sun 25 Oct','2026-10-25','New','New task. Both units. Manual: unplug, remove air inlet cover, unlock filter, vacuum the external mesh of the filter assembly, refit, then hold FILTER CLEANING 3 s to reset. Do it whenever the FILTER CLEANING button turns yellow, even if before the monthly date (manual gives no fixed interval; monthly is a sensible default). Never wash it. Long overdue -> in the Sun 25 Oct catch-up. Planned date override (Last done blank until done). Sources: Hoover H-Purifier 300 user manual (UK) https://d15v10x8t3bz3x.cloudfront.net/Libretti/2020/10/16033331/48032691_H-Purifier%20300%20UM%20UK ; U97 filter kit (Hoover UK) https://www.hoover-home.com/en_GB/products/35602347-u97-filterkit ; eSpares U97 listing (fits H-Purifier 300, ''replace annually'') https://www.espares.co.uk/product/es1828478/air-purifier-u97-h-trifilter',null from _me;
